<?php $visuals=$meta['evidence']['artifacts']??[];if($visuals): $visualsCurrent=ra_current($result); ?>
<section id="visual-artifacts" class="research-visuals"><h2>Visual research artifacts</h2><p>Explore the evidence, backing data, assumptions and limits of each research aid.</p><?php if(!$visualsCurrent): ?><p class="notice"><?=e($admission==='accepted'?'Inspect the retained specifications and backing data below. Visual previews and downloads require the current completed result.':'Visual previews and downloads require a current completed result; this packet is not accepted evidence.')?></p><?php endif ?>
<div class="artifact-cards"><?php foreach($visuals as $visual): ?><article class="task-brief" id="visual-spec-<?=e($visual['id'])?>"><div class="row-top"><span class="category"><?=e($visual['kind']==='interactive'?'Interactive page':$visual['kind'])?></span><span class="status"><?=e($visual['provenance'])?></span></div><h3><?=e($visual['title'])?></h3><?=prose($visual['purpose'])?><p class="fine">Claims: <?=e(implode(', ',$visual['claim_ids']))?> · <?=count($visual['dataset_ids'])?> backing dataset(s)</p><?php if($visualsCurrent): ?><a class="button" href="<?=e($base)?>/results/<?=e($result['id'])?>/artifacts/<?=e($visual['id'])?>">Explore artifact</a><?php endif ?><?php if(!$visualsCurrent&&$admission==='accepted'): $backing=array_values(array_filter($meta['evidence']['datasets']??[],fn($dataset)=>in_array($dataset['id'],$visual['dataset_ids'],true))); ?><details class="research-disclosure" data-retained-visual-spec><summary>Visual specification and backing data</summary><pre><?=e(json_encode(['artifact'=>$visual,'datasets'=>$backing],JSON_PRETTY_PRINT|JSON_UNESCAPED_SLASHES|JSON_THROW_ON_ERROR))?></pre></details><?php endif ?></article><?php endforeach ?></div></section><?php endif ?>
